//! National and regional CRSs converted through `proj4rs`, and listed in the SRS catalogue:
//! each code's PROJ definition (from the EPSG registry, as PROJ 9 gives it), with the datum
//! shift to WGS 84 of the EPSG transformation PROJ picks when no grid is used (`+towgs84`,
//! position-vector convention), its OGC WKT 1 and its area of use (rounded to 0.01°).
//! Datum shifts by 7 parameters are good to about a metre; ETRS89 realisations are taken as
//! WGS 84, as for the CRSs in `crs.rs`.

/// One national CRS.
pub(crate) struct National {
    pub code: u32,
    pub name: &'static str,
    pub proj4: &'static str,
    /// OGC WKT 1, as PostGIS's `spatial_ref_sys.srtext`.
    pub wkt: &'static str,
    /// West, south, east, north, in degrees.
    pub area: [f64; 4],
}

